<script setup>import {ref} from 'vue';const active=ref('general');const store=ref({name:'VORA Global',email:'support@vora.io',description:'Premium industrial technology and precision instruments for enterprise applications.',address:'100 Innovation Drive',city:'San Jose',state:'CA',postal:'95110',country:'United States'});const tabs=['general','localization','payments','shipping','taxes','security']</script><template><div><div class="page-head"><div><span class="eyebrow">ELECTROCORP ADMIN</span><h1>Store Configuration</h1><p>Manage your global store settings, localization preferences, and core operational parameters.</p></div><div><button class="button button-ghost">Discard Changes</button><button class="button button-blue">Save Settings</button></div></div><div class="settings-tabs"> <button v-for="t in tabs" :key="t" :class="{active:active===t}" @click="active=t">{{t}}</button></div><section class="panel form-panel" v-if="active==='general'"><h2>Store Identity</h2><div class="form-grid"><label>Store Name<input v-model="store.name"></label><label>Support Email<input v-model="store.email"></label><label class="full-field">Store Description (SEO)<textarea v-model="store.description"></textarea></label></div><h2>Digital Assets & Physical Address</h2><div class="form-grid"><label>Address Line 1<input v-model="store.address"></label><label>City<input v-model="store.city"></label><label>State / Province<input v-model="store.state"></label><label>Postal Code<input v-model="store.postal"></label><label>Country<input v-model="store.country"></label></div><div class="storage"><b>Storage Usage</b><span>42.5 GB of 100 GB</span><div><i style="width:42.5%"></i></div></div></section><section v-else class="panel empty-state"><h2>{{active}}</h2><p>This configuration section is intentionally kept as a thin API-backed surface until the backend contract is finalized.</p></section></div></template>
